#include "../../BaseTest.Bridge.h"

// forward declarations - TS hoists function declarations, C++ does not
void testIncrementingNonce();

void testIncrementingNonce() {
  ccxt::Exchange exchange = ccxt::Exchange(ccxt::dict{
      {std::string("id"), std::string("sampleexchange")},
  });
  // seed lastNonce above the current clock so two successive calls land in the
  // same tick and must return n and n + 1 deterministically (avoids a
  // second-boundary flake)
  ccxt::any seed = 9999999999999;
  ::setValue(::getValue(exchange, std::string("options")),
             std::string("lastNonce"), seed);
  ccxt::any first = exchange.incrementingNonce();
  ccxt::any second = exchange.incrementingNonce();
  assertTrue(
      isGreaterThan(first, seed),
      std::string("incrementingNonce should bump past the stored lastNonce"));
  assertTrue(isEqual(second, add(first, 1)),
             std::string("two incrementingNonce calls in the same tick should "
                         "return n and n + 1"));
  assertTrue(isGreaterThan(second, first),
             std::string("incrementingNonce should be strictly increasing"));
}
